const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

async function fetchUser(id) {
  if (!id) throw Object.assign(new Error('Missing id'), { status: 400 });
  return { id, name: 'Ada' };
}

